import{z as o,x as s,o as e,c as n,q as A,j as t,D as E,d as i,s as r,S as B}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"博弈论基础的 RL 映射","description":"","frontmatter":{"title":"博弈论基础的 RL 映射","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sgt-game-rl-map.md","filePath":"llm/sgt-game-rl-map.md","lastUpdated":1791413859000}'),m={name:"llm/sgt-game-rl-map.md"};function p(d,a,D,_,h,C){const l=s("Mermaid");return e(),n("div",null,[a[2]||(a[2]=A('<h1 id="博弈论基础的-rl-映射" tabindex="-1">博弈论基础的 RL 映射 <a class="header-anchor" href="#博弈论基础的-rl-映射" aria-label="Permalink to &quot;博弈论基础的 RL 映射&quot;">​</a></h1><div class="epigraph"><p>两个人以上、利益不完全一致的环境里，最优动作取决于别人会怎么做；RL 把对手写进转移函数，博弈论把转移函数里那个「别人」也写成正在学习的人。</p><footer>—— 据 Shapley, Stochastic Games, 1953；Littman, Markov games as a framework for multi-agent RL, 1994 整理</footer></div><p><a href="/llm/continual-map">上一课</a>把「在线与持续学习」收束成一张图：遗忘、回放、LoRA 生命周期、漂移与评测在那门课里各自成课，末课只留地图。本课开启「自博弈与博弈论深化」。主干课已经写过<a href="/llm/self-play-lm">自博弈</a>的做法面——两个模型互为对手互相提升；本课程要补的是它脚下的理论面：自博弈在什么条件下成立、什么时候循环不收敛、语言模型把哪些假设弄松了。本课先把博弈论的基本对象一一映射到 RL 词汇上，后课的均衡、FSP、PSRO 都默认这张映射表已在手。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单智能体 RL 的收敛故事依赖一个隐藏假设：环境不动。转移函数 \\(p(s&#39;\\mid s,a)\\) 与奖励 \\(r(s,a)\\) 由物理或仿真器固定，策略改善只会让回报单调变好。自博弈打破这个假设：你的对手是另一个策略，而且它也在被同一个损失更新。于是环境变成「别人眼中的你」的函数——昨天最优的招，今天对手已经会拆。缺口不是重新学一遍 RL，而是换一套记账单位：从「回报」换到「对手条件下的回报」。</p><p>博弈论恰好是为这种记账发明的。规范式博弈给每个参与者一个策略集 \\(\\Delta(A_i)\\) 与效用 \\(u_i\\)；随机博弈把一串阶段博弈用状态 \\(s\\) 串起来——这正是 MDP 的多人版。Littman 1994 把 Markov games 引进 RL 时给的判断至今成立：只要环境里有别的学习者，价值函数就必须对「对方策略」条件化，否则估值本身在漂。</p><p><span class="marginnote">「记账单位换成对手条件下的回报」翻译成大白话：成绩单换了科目。以前你这一手得多少分只看环境；现在同一招对新手满分类、对高手可能零分——打分前必须先写上「对面是谁」，否则分数本身没有意义。</span></p><h3 id="映射表" tabindex="-1">映射表 <a class="header-anchor" href="#映射表" aria-label="Permalink to &quot;映射表&quot;">​</a></h3><p>对象对齐是本课的全部产出：MDP 对应单人随机博弈；策略 \\(\\pi(a\\mid s)\\) 对应混合策略，即动作分布上的分布；回报对应效用 \\(u_i\\)；on-policy 采样对应「按当前策略联合行动」；环境平稳性对应「对手策略固定」。零和两人博弈里 \\(u_1=-u_2\\)，minimax 有一条成熟理论；一般和博弈——辩论、协商、多模型竞争用户——没有这个免费午餐，这是后课反复回头的前提。</p><p><span class="marginnote">von Neumann 1928 的 minimax 定理已经保证零和两人规范式博弈存在均衡：每个可解出值的博弈里「攻守同价」。RL 映射不是发明新对象，而是把 1928 年以来的记账接上梯度下降。</span></p>',10)),(e(),t(B,null,{default:E(()=>[r(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MDP%5B%22MDP%EF%BC%9A%E5%9B%BA%E5%AE%9A%E7%8E%AF%E5%A2%83%22%5D%20--%3E%20SG%5B%22%E9%9A%8F%E6%9C%BA%E5%8D%9A%E5%BC%88%EF%BC%9A%E5%AF%B9%E6%89%8B%E5%9C%A8%E7%8E%AF%E5%A2%83%E9%87%8C%22%5D%0A%20%20SG%20--%3E%20ZS%5B%22%E9%9B%B6%E5%92%8C%E4%B8%A4%E4%BA%BA%EF%BC%9A%E5%8F%AF%E8%A7%A3%20minimax%22%5D%0A%20%20SG%20--%3E%20GS%5B%22%E4%B8%80%E8%88%AC%E5%92%8C%EF%BC%9A%E8%BE%A9%E8%AE%BA%E3%80%81%E5%8D%8F%E5%95%86%22%5D%0A%20%20ZS%20--%3E%20EQ%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%9D%87%E8%A1%A1%E4%B8%8E%E6%94%B6%E6%95%9B%22%5D%0A%20%20GS%20--%3E%20EQ%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>对象映射表</strong>：把博弈论词汇逐项对齐到 RL——随机博弈对多人版 MDP、混合策略对动作分布上的分布、效用对回报——对齐的判据只有一条：环境里出现别的学习者时，记账单位必须换成对手条件下的回报。方法上刻意不做两件事：不引入收敛结论（那是后课的命题），不改更新器（PPO、GRPO 原样可用，变的只是采样对手那份 roll-out 由谁出）。本课交付的是词汇表与三处不许越界的边界。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>映射之后，训练动力学的性质整体改变。单智能体里，策略梯度沿着回报曲面上升，停滞点就是局部最优；自博弈里回报曲面本身随策略移动，「梯度在动过的地形上追最高点」，停滞点可以是纳什均衡，也可以是无人满意的循环。所以自博弈的工程问题从来不是「怎么加梯度」，而是「怎么选对手」——对手分布就是你的环境设计，这是<a href="/llm/player-selection-bias">自博弈的对手选择</a>在主干里立过的事实，本课程后几课给它配理论。</p><p>这张图回答的问题是：单智能体与自博弈的训练动力学差在哪、工程杠杆因此挪到了哪里。</p>',5)),(e(),t(B,null,{default:E(()=>[r(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SA%5B%22%E5%8D%95%E6%99%BA%E8%83%BD%E4%BD%93%EF%BC%9A%E5%9C%B0%E5%BD%A2%E5%9B%BA%E5%AE%9A%22%5D%20--%3E%20CLIMB%5B%22%E7%AD%96%E7%95%A5%E6%A2%AF%E5%BA%A6%E6%B2%BF%E5%9B%9E%E6%8A%A5%E6%9B%B2%E9%9D%A2%E4%B8%8A%E5%8D%87%22%5D%0A%20%20CLIMB%20--%3E%20LO%5B%22%E5%81%9C%E6%BB%9E%E7%82%B9%20%3D%20%E5%B1%80%E9%83%A8%E6%9C%80%E4%BC%98%22%5D%0A%20%20SP%5B%22%E8%87%AA%E5%8D%9A%E5%BC%88%EF%BC%9A%E5%AF%B9%E6%89%8B%E4%B9%9F%E5%9C%A8%E5%AD%A6%22%5D%20--%3E%20MOVE%5B%22%E5%9B%9E%E6%8A%A5%E6%9B%B2%E9%9D%A2%E9%9A%8F%E7%AD%96%E7%95%A5%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20MOVE%20--%3E%20WHERE%5B%22%E5%81%9C%E6%BB%9E%E7%82%B9%20%3D%20%E5%9D%87%E8%A1%A1%20%E6%88%96%20%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20WHERE%20--%3E%20OPP%7B%22%E5%AF%B9%E6%89%8B%E5%88%86%E5%B8%83%E6%80%8E%E4%B9%88%E9%80%89%22%7D%0A%20%20OPP%20--%3E%7C%22%E9%80%89%E5%BE%97%E5%A5%BD%22%7C%20GOOD%5B%22%E8%AF%BE%E7%A8%8B%E6%95%88%E5%BA%94%EF%BC%9A%E6%8E%A8%E5%90%91%E5%9D%87%E8%A1%A1%22%5D%0A%20%20OPP%20--%3E%7C%22%E9%80%89%E5%BE%97%E5%B7%AE%22%7C%20BAD%5B%22%E6%8C%AF%E8%8D%A1%EF%BC%9A%E6%98%A8%E5%A4%A9%E6%9C%80%E4%BC%98%E4%BB%8A%E5%A4%A9%E4%BD%9C%E5%BA%9F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<p>第二处机制差异在信用分配：对手的失误算你的功劳还是运气？零和博弈可以用可利用度（exploitability）——被最优对手打穿的程度——做绝对标尺；一般和与语言任务里没有可算的标尺，只能靠评测集，而评测集也会被博弈，这个坑留给收束课。PPO、GRPO 这些更新器<a href="/llm/ppo-llm">原样可用</a>，变的只是采样对手那份 roll-out 由谁出。</p><p><span class="marginnote">数字实例：零和博弈里若算出可利用度 0.5，意思是来了一个理论上最优的对手，平均每局能比你多赢 0.5 分；把它压到 0.01，才说明几乎没人能打穿你。它像「被职业选手虐的程度」，数值越低策略越接近无懈可击。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>映射有三处不许越界。其一，博弈论的均衡概念是对「无限理性、无限样本」的极限描述，不承诺有限算力的学习过程到达它；其二，随机博弈仍假设状态可观测、转移可采样，语言博弈的「状态」是对话历史加双方不可见的意图，采样靠生成；其三，本课只对齐词汇，不引入任何收敛结论——「自博弈趋于均衡」是下一课要专门拆解的命题，这里不给保证。</p><p><span class="marginnote">常见误区：以为「存在纳什均衡」等于「训练会自动走到它」。均衡是无限理性、无限样本下的极限描述，好比「两点之间直线最短」并不保证你走路真能走直线——有限算力的学习过程可能永远在路上，甚至绕圈。</span></p><p>后课默认你已经把「对手是环境的一部分，而且是会变的那部分」当成第一性事实：谈均衡、对手池、辩论与协商时，都在回答同一个问题——这条会变的环境，怎么走才不会白学。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自博弈把 RL 的固定环境假设换成「对手也是学习者」，记账单位必须换成对手条件下的回报。</li><li>映射表：混合策略对策略分布、随机博弈对 MDP 的多人版、效用对回报；零和有 minimax 理论，一般和没有。</li><li>自博弈的核心工程量在对手分布的选取，不在策略梯度本身。</li><li>均衡是极限概念，本课不给任何「自博弈会到均衡」的承诺。</li><li>出处：Shapley 1953（随机博弈）；Littman 1994（Markov games 与 RL）；von Neumann 1928（minimax 定理）。</li></ul>',8))])}const c=o(m,[["render",p]]);export{P as __pageData,c as default};
